mapper.select:
select
*
from t_operate_log


        AND operate_user_id = #{query.operateUserId}


        AND operate_user_type = #{query.operateUserType}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') >= #{query.startDate}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') <= #{query.endDate}


        AND operate_user_name ILIKE CONCAT('%', #{query.userName}, '%')


        AND (module ILIKE CONCAT('%', #{query.keywords}, '%') OR content ILIKE CONCAT('%', #{query.keywords}, '%'))


        AND (url ILIKE CONCAT('%', #{query.requestKeywords}, '%') OR method ILIKE CONCAT('%', #{query.requestKeywords}, '%') OR param ILIKE CONCAT('%', #{query.requestKeywords}, '%') OR response ILIKE CONCAT('%', #{query.requestKeywords}, '%'))


        AND success = #{query.successFlag}


order by create_time desc
